def num(state, key):
    return int(str(state.get(key, '0')).strip())

def put(state, key, value):
    state[key] = str(value)

def copy_value(state, dst, src):
    if src in state:
        state[dst] = state[src]

def add_line(state, key, value):
    state.pop(key, None)
    state[key] = value

def transfer_owner(state, old, new):
    for k in list(state.keys()):
        if k.endswith('.owner') and state[k] == old:
            state[k] = new

